//! OCTET bounded binary protocol primitives.
const std=@import("std");pub const MAGIC="OCT1";pub const HEADER_LEN:usize=10;pub const VERSION:u8=1;
pub const Error=error{OutputTooSmall,InputTooShort,BadMagic,UnsupportedVersion,LengthMismatch,PayloadTooLarge,InvalidUtf8,InvalidFieldId,InvalidWireType,TruncatedField};
pub const FrameView=struct{version:u8,flags:u8,payload:[]const u8};pub const FieldView=struct{id:u16,wire_type:u8,value:[]const u8};
pub fn encode(flags:u8,p:[]const u8,o:[]u8,max:usize)Error![]u8{if(p.len>max or p.len>0xffff_ffff)return Error.PayloadTooLarge;const n=10+p.len;if(o.len<n)return Error.OutputTooSmall;@memcpy(o[0..4],MAGIC);o[4]=1;o[5]=flags;var l:[4]u8=undefined;std.mem.writeInt(u32,&l,@intCast(p.len),.big);@memcpy(o[6..10],&l);@memcpy(o[10..n],p);return o[0..n];}
pub fn decode(i:[]const u8,max:usize)Error!FrameView{if(i.len<10)return Error.InputTooShort;if(!std.mem.eql(u8,i[0..4],MAGIC))return Error.BadMagic;if(i[4]!=1)return Error.UnsupportedVersion;var l:[4]u8=undefined;@memcpy(&l,i[6..10]);const n:usize=@intCast(std.mem.readInt(u32,&l,.big));if(n>max)return Error.PayloadTooLarge;if(i.len!=10+n)return Error.LengthMismatch;return .{.version=i[4],.flags=i[5],.payload=i[10..]};}
pub fn putU16(o:[]u8,v:u16)Error![]u8{if(o.len<2)return Error.OutputTooSmall;std.mem.writeInt(u16,o[0..2],v,.big);return o[0..2];}
pub fn putU32(o:[]u8,v:u32)Error![]u8{if(o.len<4)return Error.OutputTooSmall;std.mem.writeInt(u32,o[0..4],v,.big);return o[0..4];}
pub fn putU64(o:[]u8,v:u64)Error![]u8{if(o.len<8)return Error.OutputTooSmall;std.mem.writeInt(u64,o[0..8],v,.big);return o[0..8];}
pub fn getU16(i:[]const u8)Error!u16{if(i.len<2)return Error.InputTooShort;return std.mem.readInt(u16,i[0..2],.big);}
pub fn getU32(i:[]const u8)Error!u32{if(i.len<4)return Error.InputTooShort;return std.mem.readInt(u32,i[0..4],.big);}
pub fn getU64(i:[]const u8)Error!u64{if(i.len<8)return Error.InputTooShort;return std.mem.readInt(u64,i[0..8],.big);}
pub fn putBytes(a:std.mem.Allocator,v:[]const u8,max:usize)Error![]u8{if(v.len>max or v.len>0xffff_ffff)return Error.PayloadTooLarge;const o=a.alloc(u8,4+v.len)catch return Error.OutputTooSmall;std.mem.writeInt(u32,o[0..4],@intCast(v.len),.big);@memcpy(o[4..],v);return o;}
pub fn getBytes(i:[]const u8,max:usize)Error![]const u8{if(i.len<4)return Error.InputTooShort;const n:usize=@intCast(std.mem.readInt(u32,i[0..4],.big));if(n>max)return Error.PayloadTooLarge;if(i.len!=4+n)return Error.LengthMismatch;return i[4..];}
pub fn putString(a:std.mem.Allocator,v:[]const u8,max:usize)Error![]u8{if(!std.unicode.utf8ValidateSlice(v))return Error.InvalidUtf8;return putBytes(a,v,max);}
pub fn getString(i:[]const u8,max:usize)Error![]const u8{const v=try getBytes(i,max);if(!std.unicode.utf8ValidateSlice(v))return Error.InvalidUtf8;return v;}
pub fn appendField(o:[]u8,id:u16,wt:u8,v:[]const u8)Error![]u8{if(id==0)return Error.InvalidFieldId;if(wt>3)return Error.InvalidWireType;if(o.len<7+v.len)return Error.OutputTooSmall;std.mem.writeInt(u16,o[0..2],id,.big);o[2]=wt;std.mem.writeInt(u32,o[3..7],@intCast(v.len),.big);@memcpy(o[7..][0..v.len],v);return o[0..7+v.len];}
pub fn readField(i:[]const u8)Error!struct{field:FieldView,rest:[]const u8}{if(i.len<7)return Error.TruncatedField;const id=std.mem.readInt(u16,i[0..2],.big);if(id==0)return Error.InvalidFieldId;const wt=i[2];if(wt>3)return Error.InvalidWireType;const n:usize=@intCast(std.mem.readInt(u32,i[3..7],.big));if(i.len<7+n)return Error.TruncatedField;return .{.field=.{.id=id,.wire_type=wt,.value=i[7..7+n]},.rest=i[7+n..]};}
test "frame and integer roundtrip"{var b:[64]u8=undefined;const w=try encode(2,"hello",&b,32);const f=try decode(w,32);try std.testing.expectEqualStrings("hello",f.payload);var n:[4]u8=undefined;_=try putU32(&n,0x12345678);try std.testing.expectEqual(@as(u32,0x12345678),try getU32(&n));}
test "tagged fields roundtrip"{var b:[32]u8=undefined;const w=try appendField(&b,7,1,"abc");const f=try readField(w);try std.testing.expectEqual(@as(u16,7),f.field.id);try std.testing.expectEqualStrings("abc",f.field.value);}
